@Transactional(propagation = Propagation.REQUIRED, isolation = Isolation.REPEATABLE_READ, timeout = 30, rollbackFor = {DataAccessException.class, BusinessException.class})
public void executeCriticalLedgerTransfer(Long sourceAccountId, Long targetAccountId, BigDecimal amount) {
    Account sourceAccount = accountRepository.findByIdForUpdate(sourceAccountId)
        .orElseThrow(() -> new AccountNotFoundException(sourceAccountId));

    if (sourceAccount.getBalance().compareTo(amount) < 0) {
        throw new InsufficientFundsException("Insufficient balance for account: " + sourceAccountId);
    }

    accountRepository.debit(sourceAccountId, amount);
    accountRepository.credit(targetAccountId, amount);
    auditLogRepository.recordTransfer(sourceAccountId, targetAccountId, amount);
}
